import re
from abc import ABCMeta
from collections import namedtuple
from future.utils import with_metaclass
from robot import get_version
from robot.result import ExecutionResult

from taf.ul.ettf.typed.typed import typed

Version = namedtuple('Version', ['version_regex', 'class_type'])


class RobotExecutionResultBase(with_metaclass(ABCMeta)):
    def __init__(self, xml_path):
        self._result = ExecutionResult(xml_path)

    @property
    def tests(self):
        return self._result.suite.tests

    @property
    def suite(self):
        return self._result.suite

    @property
    def errors(self):
        return self._result.errors

    @typed(expected_testcase_name=str)
    def get_testcase(self, expected_testcase_name):
        matching_testcases = [testcase for testcase in self.tests if testcase.name == expected_testcase_name]
        assert len(matching_testcases) == 1, 'There should be no more than one matching testcase'
        return matching_testcases[0]

    def assert_that_suite_passes(self):
        assert self._result.suite.passed

    def assert_that_suite_fails(self):
        assert not self._result.suite.passed

    @typed(expected_testcase_name=str)
    def assert_that_testcase_passes(self, testcase_name):
        assert self.get_testcase(testcase_name, self._result).passed

    @typed(expected_testcase_name=str)
    def assert_that_testcase_fails(self, testcase_name):
        assert not self.get_testcase(testcase_name, self._result).passed


class RobotExecutionResult3(RobotExecutionResultBase):
    pass


class RobotExecutionResult4(RobotExecutionResultBase):
    pass


def _get_class_based_on_robot_version():
    versions = [
        Version('^3.*', RobotExecutionResult3),
        Version('^4.*', RobotExecutionResult4),
    ]
    for version in versions:
        if re.match(version.version_regex, get_version()):
            return version.class_type
    return RobotExecutionResult4


def RobotExecutionResult(xml_path):
    return _get_class_based_on_robot_version()(xml_path)
